package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.JsonNode;import com.ruoyi.medical.contracts.*;import com.ruoyi.medical.identity.ApplicationSessionIdentity;
import java.util.*;import java.math.BigInteger;import java.nio.charset.StandardCharsets;import java.util.function.Consumer;
import org.springframework.util.function.ThrowingSupplier;import org.springframework.transaction.support.TransactionSynchronizationManager;
/** Two-stage EVALUATION-only context materialization. No public request bytes, grant booleans, artifact IDs or provider invocation are manufactured. */
public final class FormalEvaluationExactInputPreparation {
 private static final String GOVERNANCE="AGENT_PUBLICATION";private static final DependencyLineage.Limits LIMITS=new DependencyLineage.Limits(512,2048);
 private final EnterpriseAccess access;private final FormalEvaluationContextStore contexts;private final FormalEvaluationModelPreparation models;
 private final FormalCapabilityIdentityAuthority capabilities;private final FormalRuntimeCapabilityIdentityAuthority components;private final FormalEvaluationContextPackages packages;
 private final ScopeSnapshotStore snapshots;private final SourceReadAuthority sources;private final FormalInvocationSourceOriginals originals;private final FormalTokenizerRunner tokenizer;
 private final ModelConfigurationService configurations;private final RunTokenAuthoritySchema roleSchema;private final PermissionSchema json;private final SchemaCatalogue catalogue;private final BuiltinEvaluationDocumentContextCompiler compiler;
 public FormalEvaluationExactInputPreparation(EnterpriseAccess access,FormalEvaluationContextStore contexts,FormalEvaluationModelPreparation models,FormalCapabilityIdentityAuthority capabilities,FormalRuntimeCapabilityIdentityAuthority components,FormalEvaluationContextPackages packages,ScopeSnapshotStore snapshots,SourceReadAuthority sources,FormalInvocationSourceOriginals originals,FormalTokenizerRunner tokenizer,ModelConfigurationService configurations,RunTokenAuthoritySchema roleSchema,PermissionSchema json,SchemaCatalogue catalogue){this.access=access;this.contexts=contexts;this.models=models;this.capabilities=capabilities;this.components=components;this.packages=packages;this.snapshots=snapshots;this.sources=sources;this.originals=originals;this.tokenizer=tokenizer;this.configurations=configurations;this.roleSchema=roleSchema;this.json=json;this.catalogue=catalogue;this.compiler=new BuiltinEvaluationDocumentContextCompiler(catalogue,json);}
 public static final class Capture {
  private final FormalEvaluationExactInputPreparation owner;private final String tenant,actor,session,context,project,rootCanonical;private final FormalEvaluationExecutionInputs.Prepared inputs;private final FormalEvaluationExecutionScopes.Prepared scope;
  private final PermissionProtocol.Basis contextBinding;private final FormalEvaluationContextProtocol.Node binding;private final FormalEvaluationExecutionProtocol.Node node;
  private final FormalEvaluationContextPackages.Plan tool,prompt;private final ScopeSnapshotStore.Stored promptSnapshot;private final JsonNode document,receipt;private String witness;
  private Capture(FormalEvaluationExactInputPreparation owner,EnterpriseAccess.Admission a,FormalEvaluationExecutionInputs.Prepared inputs,FormalEvaluationExecutionScopes.Prepared scope,FormalEvaluationContextStore.Approved approved,FormalEvaluationExecutionProtocol.Node node,FormalEvaluationExecutionAdmission.Prepared root,FormalEvaluationContextPackages.Plan tool,FormalEvaluationContextPackages.Plan prompt,ScopeSnapshotStore.Stored snapshot,JsonNode document,JsonNode receipt){this.owner=owner;tenant=a.context().tenant_id();actor=a.actorId();session=a.subject().sessionId();context=a.context().context_revision();project=root.projectId();rootCanonical=root.canonical();this.inputs=inputs;this.scope=scope;contextBinding=approved.binding();binding=approved.node(node.nodeKind());this.node=node;this.tool=tool;this.prompt=prompt;promptSnapshot=snapshot;this.document=document.deepCopy();this.receipt=receipt.deepCopy();}
 }
 /** Inside the real admission transaction; the extra prompt snapshot has independently explicit governance purpose. */
 public Capture capture(EnterpriseAccess.Admission a,FormalEvaluationExecutionInputs.Prepared inputs,FormalEvaluationExecutionScopes.Prepared scope,FormalEvaluationModelPreparation.Prepared model,FormalEvaluationContextStore.Approved approved,FormalEvaluationExecutionProtocol.Node node)throws Exception{
  if(node==null||!"N01".equals(node.nodeKind()))throw new TenantAccessException(ErrorCode.DEPENDENCY_UNAVAILABLE);var root=inputs.requireCurrent(a);scope.requireCurrent(a);model.requireCurrent(a);same(node,model.node());if(!root.nodes().contains(node)||node.model()==null)bad();approved.requireConsumer(a,node.cell().candidate(),node.cell().policy());
  var binding=approved.node(node.nodeKind());same(node.role(),binding.role());String abiHash=catalogue.schemaDigest("evaluation-context-compiler");
  var tool=components.require(a,binding.contextAssembler(),"TOOL",root.projectId(),"EVALUATION_RESULTS");var prompt=capabilities.require(a,binding.prompt(),"PROMPT",root.projectId(),"EVALUATION_RESULTS");
  var toolPlan=packages.plan(a,a.context().context_revision(),root.projectId(),tool.sourceArtifact(),BuiltinEvaluationDocumentContextCompiler.PACKAGE,abiHash);
  var promptPlan=packages.plan(a,a.context().context_revision(),root.projectId(),prompt.sourceArtifact(),BuiltinEvaluationDocumentContextCompiler.PROMPT,abiHash);
  if(promptPlan.sources().isEmpty())throw new TenantAccessException(ErrorCode.DEPENDENCY_UNAVAILABLE);
  var sourceScope=sourceScope(promptPlan);var policy=root.policy();
  var promptScope=snapshots.saveForEvaluation(a,root.projectId(),scope.profileRevision(),sourceScope,root.request().evaluationId(),GOVERNANCE,policy.environment(),policy.region(),LIMITS);
  // Document comes exclusively from079's private physical-read proof. expected_ref is never loaded or passed to the compiler.
  var captured=new Capture(this,a,inputs,scope,approved,node,root,toolPlan,promptPlan,promptScope,inputs.document(a,node.cell().sampleId()),inputs.receipt(a,node.cell().sampleId()));
  captured.witness=current(a,captured);tool.requireUnchanged();prompt.requireUnchanged();approved.requireUnchanged();model.requireCurrent(a);return captured;
 }
 /** Outside every tenant transaction: actual package originals, actual built-in implementation, actual executable tokenizer. */
 public PreparedExactInput materialize(ApplicationSessionIdentity.Verified subject,String context,Capture captured)throws Exception{
  if(captured==null||captured.owner!=this)denied();if(TransactionSynchronizationManager.isActualTransactionActive())throw new TenantAccessException(ErrorCode.CONTEXT_CHANGED);same(context,captured.context);
  recheck(subject,captured);var tool=packages.read(subject,captured.tool);recheck(subject,captured);var prompt=packages.read(subject,captured.prompt);recheck(subject,captured);
  var compiled=compiler.compile(tool.bytes(),prompt.bytes(),captured.document,captured.binding);recheck(subject,captured);
  var tokenizerPlan=access.execute(subject,a->ThrowingSupplier.of(()->{same(captured.witness,current(a,captured));var root=captured.inputs.requireCurrent(a);var declared=root.policy().bindings().stream().filter(b->b.nodeKind().equals(captured.node.nodeKind())).findFirst().orElseThrow().tokenizerArtifact();return packages.plan(a,context,captured.project,captured.node.tokenizer(),declared.schema().schemaRef(),declared.schema().schemaSha256());}).get());
  var tokenizerArtifact=packages.read(subject,tokenizerPlan);var executableBasis=tokenizer.configuredSourceBasis();same(captured.node.tokenizer().content_sha256(),executableBasis.content_sha256());if(!tokenizerPlan.sources().contains(executableBasis.version_id()))throw new TenantAccessException(ErrorCode.DEPENDENCY_UNAVAILABLE);
  var executable=originals.read(subject,context,executableBasis,"MODEL_CONFIGURATION",captured.project);same(captured.node.tokenizer().content_sha256(),org.apache.commons.codec.digest.DigestUtils.sha256Hex(executable.bytes()));if(!Arrays.equals(tokenizerArtifact.bytes(),executable.bytes()))bad();
  recheck(subject,captured);var result=tokenizer.count(compiled.bytes(),executableBasis.version_id(),executableBasis.content_sha256(),()->Thread.currentThread().isInterrupted());
  same(compiled.sha256(),result.inputSha256());same(executableBasis.version_id(),result.tokenizerVersion());same(executableBasis.content_sha256(),result.executableSha256());
  var prepared=new PreparedExactInput(this,captured,tool,prompt,tokenizerArtifact,executable,compiled,result);
  access.execute(subject,a->ThrowingSupplier.of(()->{var root=captured.inputs.requireCurrent(a);prepared.requireCurrent(a,root,captured.node);return null;}).get());return prepared;
 }
 public static final class PreparedExactInput {
  private final FormalEvaluationExactInputPreparation owner;private final Capture capture;private final FormalEvaluationContextPackages.Read tool,prompt,tokenizerArtifact;private final FormalInvocationSourceOriginals.Read executable;
  private final BuiltinEvaluationDocumentContextCompiler.Compilation compiled;private final FormalTokenizerRunner.Result tokens;
  private PreparedExactInput(FormalEvaluationExactInputPreparation owner,Capture capture,FormalEvaluationContextPackages.Read tool,FormalEvaluationContextPackages.Read prompt,FormalEvaluationContextPackages.Read tokenizerArtifact,FormalInvocationSourceOriginals.Read executable,BuiltinEvaluationDocumentContextCompiler.Compilation compiled,FormalTokenizerRunner.Result tokens){this.owner=owner;this.capture=capture;this.tool=tool;this.prompt=prompt;this.tokenizerArtifact=tokenizerArtifact;this.executable=executable;this.compiled=compiled;this.tokens=tokens;}
  public void requireCurrent(EnterpriseAccess.Admission a,FormalEvaluationExecutionAdmission.Prepared root,FormalEvaluationExecutionProtocol.Node node)throws Exception{
   same(capture.node,node);root.requireConsumer(a,capture.inputs.request());same(capture.rootCanonical,root.canonical());same(capture.witness,owner.current(a,capture));tool.requireCurrent(a);prompt.requireCurrent(a);tokenizerArtifact.requireCurrent(a);executable.requireCurrent(a);same(new PermissionProtocol.Basis(tokens.tokenizerVersion(),tokens.executableSha256()),owner.tokenizer.configuredSourceBasis());
   same(compiled.implementationSha256(),owner.compiler.implementationClassSha256());same(compiled.sha256(),tokens.inputSha256());owner.capacity(a,capture,tokens.tokenCount());
  }
  public void consume(EnterpriseAccess.Admission a,FormalEvaluationExecutionAdmission.Prepared root,FormalEvaluationExecutionProtocol.Node node,Consumer<byte[]> consumer)throws Exception{requireCurrent(a,root,node);consumer.accept(compiled.bytes());requireCurrent(a,root,node);}
  public String inputSha256(){return compiled.sha256();}public FormalTokenizerRunner.Result tokenization(){return tokens;}
  public JsonNode evidence(EnterpriseAccess.Admission a,FormalEvaluationExecutionAdmission.Prepared root,FormalEvaluationExecutionProtocol.Node node)throws Exception{
   requireCurrent(a,root,node);var w=owner.json.object().put("schema_version","1.0.0").put("purpose","EVALUATION_RESULTS").put("context_mode","DOCUMENT_ONLY").put("tool_mode","NONE").put("upstream_mode","NONE").put("implementation_id",BuiltinEvaluationDocumentContextCompiler.IMPLEMENTATION).put("implementation_version",BuiltinEvaluationDocumentContextCompiler.VERSION).put("implementation_class_sha256",compiled.implementationSha256()).put("compilation_input_sha256",compiled.inputSha256()).put("exact_input_sha256",compiled.sha256()).put("exact_input_schema_ref",BuiltinEvaluationDocumentContextCompiler.OUTPUT).put("exact_input_schema_sha256",owner.catalogue.schemaDigest("simulation-execution")).put("authorization_sha256",org.apache.commons.codec.digest.DigestUtils.sha256Hex(capture.witness.getBytes(StandardCharsets.UTF_8)));
   w.set("context_binding",owner.json.tree(capture.contextBinding));w.set("node",owner.json.tree(node));w.set("source_snapshot",owner.json.tree(capture.scope.snapshot()));w.set("prompt_source_snapshot",owner.json.tree(new PermissionProtocol.Basis(capture.promptSnapshot.snapshot().snapshotId(),capture.promptSnapshot.snapshot().manifestHash())));w.set("role",owner.json.tree(capture.binding.role()));w.set("prompt",owner.json.tree(capture.binding.prompt()));w.set("assembler",owner.json.tree(capture.binding.contextAssembler()));w.set("input_receipt",capture.receipt.deepCopy());w.set("tool_original",tool.witness());w.set("prompt_original",prompt.witness());
   var measured=owner.json.object().put("tokenizer_version",tokens.tokenizerVersion()).put("executable_sha256",tokens.executableSha256()).put("input_sha256",tokens.inputSha256()).put("output_sha256",tokens.outputSha256()).put("token_count",tokens.tokenCount().toString()).put("source_authorization_sha256",executable.authorizationSha256());w.set("tokenizer_artifact_basis",owner.json.tree(capture.node.tokenizer()));w.set("execution_source_basis",owner.json.tree(new PermissionProtocol.Basis(executable.sourceVersion(),executable.contentSha256())));w.set("tokenizer_artifact_original",tokenizerArtifact.witness());w.set("tokenization",measured);return w;
  }
 }
 private String current(EnterpriseAccess.Admission a,Capture c)throws Exception{
  FormalEvaluationExecutionAdmission.current(a);same(c.tenant,a.context().tenant_id());same(c.actor,a.actorId());same(c.session,a.subject().sessionId());same(c.context,a.context().context_revision());
  var root=c.inputs.requireCurrent(a);same(c.rootCanonical,root.canonical());c.scope.requireCurrent(a);var model=models.require(a,c.inputs,c.scope,c.node);model.requireCurrent(a);
  var approved=contexts.requireApproved(a,c.contextBinding,c.node.cell().candidate(),c.node.cell().policy());approved.requireConsumer(a,c.node.cell().candidate(),c.node.cell().policy());same(c.binding,approved.node(c.node.nodeKind()));
  var tool=components.require(a,c.binding.contextAssembler(),"TOOL",c.project,"EVALUATION_RESULTS");var prompt=capabilities.require(a,c.binding.prompt(),"PROMPT",c.project,"EVALUATION_RESULTS");same(c.tool.artifact(),tool.sourceArtifact());same(c.prompt.artifact(),prompt.sourceArtifact());
  String abi=catalogue.schemaDigest("evaluation-context-compiler");var toolPlan=packages.plan(a,c.context,c.project,tool.sourceArtifact(),BuiltinEvaluationDocumentContextCompiler.PACKAGE,abi);var promptPlan=packages.plan(a,c.context,c.project,prompt.sourceArtifact(),BuiltinEvaluationDocumentContextCompiler.PROMPT,abi);same(c.prompt.sources(),promptPlan.sources());
  var policy=root.policy();var promptScope=snapshots.readForEvaluation(a,c.project,c.scope.profileRevision(),sourceScope(promptPlan),root.request().evaluationId(),GOVERNANCE,policy.environment(),policy.region(),LIMITS,new PermissionProtocol.Basis(c.promptSnapshot.snapshot().snapshotId(),c.promptSnapshot.snapshot().manifestHash()));same(c.promptSnapshot,promptScope);
  var role=capabilities.require(a,c.node.role(),"ROLE",c.project,"EVALUATION_RESULTS");var narrowed=roleSchema.read("RoleScope",json.canonical(role.canonicalDefinition().required("request").required("tool_scope")));
  var projectPermission=new RunTokenAuthoritySchema.Permission(new PermissionProtocol.Scope(c.tenant,c.project,"PROJECT",c.project),"project.read",GOVERNANCE);boolean projectAllowed=false;for(var allowed:narrowed.required("permissions"))if(json.tree(projectPermission).equals(allowed))projectAllowed=true;if(!projectAllowed)denied();
  var send=json.object();for(var member:promptScope.manifest().members()){
   var checked=sources.require(a,new SourceReadProtocol.ReadRequirement(member.source_version(),member.rights_revision(),c.project,promptScope.snapshot().snapshotId(),member.parse_version(),null,SourceReadProtocol.Use.MODEL_SEND,GOVERNANCE,policy.environment(),policy.region(),model.model().provider()));
   for(String action:List.of("source.read","source.external.process")){var permission=new RunTokenAuthoritySchema.Permission(new PermissionProtocol.Scope(c.tenant,checked.source().ownerProjectId(),"SOURCE",checked.source().sourceId()),action,GOVERNANCE);boolean found=false;for(var allowed:narrowed.required("permissions"))if(json.tree(permission).equals(allowed))found=true;if(!found)denied();}
   send.set(member.source_version(),AgentPublicationWitness.tree(checked));
  }
  String classification=FormalEvaluationContextPackages.max(root.classification(),promptPlan.classification(),toolPlan.classification());if(!model.model().allowed_classifications().contains(classification)||!model.model().allowed_regions().contains(policy.region())||policy.trainingAllowed()&&!model.model().allow_training())denied();
  same(c.document,c.inputs.document(a,c.node.cell().sampleId()));same(c.receipt,c.inputs.receipt(a,c.node.cell().sampleId()));
  var witness=json.object();witness.set("model",json.tree(model.model()));witness.set("node",json.tree(c.node));witness.set("binding",json.tree(c.binding));witness.set("context_binding",json.tree(c.contextBinding));witness.set("prompt_send",send);witness.set("role",role.authorizations());witness.set("prompt",prompt.authorizations());witness.set("tool",tool.authorizations());witness.put("classification",classification).put("compiler_sha256",compiler.implementationClassSha256());witness.set("scope",json.tree(c.scope.snapshot()));witness.set("prompt_scope",json.tree(promptScope.manifest()));
  approved.requireUnchanged();tool.requireUnchanged();prompt.requireUnchanged();role.requireUnchanged();model.requireCurrent(a);return json.canonical(witness);
 }
 private void capacity(EnterpriseAccess.Admission a,Capture c,BigInteger count)throws Exception{var fixed=configurations.requireCurrentExternal(a,c.node.model().version_id(),"RUN_CREATION",c.project);var definition=(ModelConfigurationProtocol.Definition)fixed.definition();var root=c.inputs.requireCurrent(a);var binding=root.policy().bindings().stream().filter(b->b.nodeKind().equals(c.node.nodeKind())).findFirst().orElseThrow();var parameters=binding.generationParameters();if(!"none".equals(parameters.required("reasoning_effort").asText()))throw new TenantAccessException(ErrorCode.MODEL_POLICY_INCOMPLETE);var output=parameters.required("max_output_tokens").bigIntegerValue();if(count.signum()<0||output.signum()<=0||output.compareTo(new BigInteger(definition.limits().max_output_tokens()))>0||count.add(output).compareTo(new BigInteger(definition.limits().context_window()))>0)throw new TenantAccessException(ErrorCode.CONTEXT_LIMIT);}
 private void recheck(ApplicationSessionIdentity.Verified subject,Capture c){access.execute(subject,a->ThrowingSupplier.of(()->{same(c.witness,current(a,c));return null;}).get());}
 private static CommonProtocol.SourceScope sourceScope(FormalEvaluationContextPackages.Plan p){return new CommonProtocol.SourceScope(CommonProtocol.ScopeMode.SOURCE_VERSIONS,List.of(),p.sources(),false,null,null);}
 private static void same(Object expected,Object actual){if(!Objects.equals(expected,actual))bad();}private static void bad(){throw new TenantAccessException(ErrorCode.CONTENT_MISMATCH);}private static void denied(){throw new TenantAccessException(ErrorCode.ACCESS_DENIED);}
}
